import { readFile, writeFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const schema = JSON.parse(await readFile(new URL('protocol/schema.json', root), 'utf8'));
const check = process.argv.includes('--check');
const snake = (key) => key.replace(/([a-z])([A-Z])/g, '$1_$2').toUpperCase();
const numbers = Object.entries(schema).filter(([, value]) => typeof value === 'number');
const c = [
  '/* Generated by tools/generate-protocol.mjs. Do not edit. */',
  '#ifndef PIXELJS_PROTOCOL_H',
  '#define PIXELJS_PROTOCOL_H',
  '#include <stdint.h>',
  '',
  ...numbers.map(([key, value]) => `#define PX_${snake(key)} UINT32_C(${value})`),
  '',
  ...Object.entries(schema.opcodes).map(
    ([key, value]) => `#define PX_OP_${key} UINT16_C(${value})`,
  ),
  '',
  ...Object.entries(schema.flags).map(
    ([key, value]) => `#define PX_FLAG_${key} UINT16_C(${value})`,
  ),
  '',
  ...Object.entries(schema.statuses).map(
    ([key, value]) => `#define PX_WIRE_${key} UINT32_C(${value})`,
  ),
  '',
  '#endif',
  '',
].join('\n');
const ts = [
  '// Generated by tools/generate-protocol.mjs. Do not edit.',
  `export const PROTOCOL = ${JSON.stringify(Object.fromEntries(numbers), null, 2)} as const;`,
  `export const OPCODE = ${JSON.stringify(schema.opcodes, null, 2)} as const;`,
  `export const FLAGS = ${JSON.stringify(schema.flags, null, 2)} as const;`,
  `export const STATUS = ${JSON.stringify(schema.statuses, null, 2)} as const;`,
  '',
].join('\n');
const artifacts = [
  ['core/include/pixeljs/protocol.h', c],
  ['packages/core/src/internal/protocol.ts', ts],
  [
    'bridge/wasm/exports.json',
    `${JSON.stringify(
      schema.exports.map((name) => `_${name}`),
      null,
      2,
    )}\n`,
  ],
];
for (const [path, expected] of artifacts) {
  const url = new URL(path, root);
  if (check) {
    let actual;
    try {
      actual = await readFile(url, 'utf8');
    } catch {
      actual = undefined;
    }
    if (actual !== expected) throw new Error(`Generated artifact differs: ${path}`);
  } else {
    await writeFile(url, expected);
  }
}
console.log(check ? 'Protocol artifacts match the schema.' : 'Protocol artifacts generated.');
